DEFAULT_NAME = 'pythinker-client'
DEFAULT_VERSION = '1.0'


def build_driver_info(name=None, version=None):
    return {
        'name': name or DEFAULT_NAME,
        'version': version or DEFAULT_VERSION,
    }

files.test_metadata.py:
from metadata import build_driver_info


def test_omitted_fields_use_defaults():
    assert build_driver_info() == {'name': 'pythinker-client', 'version': '1.0'}


def test_explicit_none_suppresses_one_field():
    assert build_driver_info(name=None) == {'version': '1.0'}
    assert build_driver_info(version=None) == {'name': 'pythinker-client'}


def test_explicit_none_for_both_fields_returns_empty_metadata():
    assert build_driver_info(name=None, version=None) == {}


def test_explicit_values_are_used():
    assert build_driver_info(name='wrapper', version='2.5') == {'name': 'wrapper', 'version': '2.5'}


def test_falsey_explicit_values_are_preserved():
    assert build_driver_info(name='', version='0') == {'name': '', 'version': '0'}
    assert build_driver_info(name=False, version=0) == {'name': False, 'version': 0}
    assert build_driver_info(name=None, version='') == {'version': ''}
